{"path": "/tmp/sv-bf366cbf07474dd7b8458053daff35c5/Components/Pages/Settings/NotificationsSection.razor", "file_text": "@namespace sv_bf366cbf07474dd7b8458053daff35c5.Components.Pages.Settings
@using sv_bf366cbf07474dd7b8458053daff35c5.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notifications</h2>

    @if (_loading)
    {
        <p class="loading">Loading notification preferences...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-row">
                <span>Email Notifications</span>
                <input type="checkbox" @bind="_emailNotifications" />
            </label>

            <label class="toggle-row">
                <span>Push Notifications</span>
                <input type="checkbox" @bind="_pushNotifications" />
            </label>

            <label class="toggle-row">
                <span>Weekly Digest</span>
                <input type="checkbox" @bind="_weeklyDigest" />
            </label>
        </div>

        <div class="channels-section">
            <h3>Muted Channels</h3>
            @foreach (var channel in _allChannels)
            {
                <label class="channel-row">
                    <input type="checkbox"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                    <span>@channel</span>
                </label>
            }
        </div>

        <div class="form-actions">
            <button class="btn-primary" @onclick="SaveAsync">Save Preferences</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Preferences saved!</div>
        }
    }
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = [];
    private bool _loading = true;
    private bool _showSuccess;

    private static readonly string[] _allChannels = ["General", "Announcements", "Engineering", "Marketing", "Support", "Random"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = [.. prefs.MutedChannels];
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, [.. _mutedChannels]);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _showSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}
"}

{"path": "/tmp/sv-bf366cbf07474dd7b8458053daff35c5/Components/Pages/Settings/ChangePasswordPanel.razor", "file_text": "@namespace sv_bf366cbf07474dd7b8458053daff35c5.Components.Pages.Settings
@using sv_bf366cbf07474dd7b8458053daff35c5.Services
@inject ISettingsService SettingsService

<div class="expandable-panel">
    <button class="panel-header" @onclick="() => _expanded = !_expanded">
        <span>Change Password</span>
        <span class="expand-icon">@(_expanded ? "▼" : "▶")</span>
    </button>

    @if (_expanded)
    {
        <div class="panel-body">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="_currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="_newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="_confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <p class="error-message">@_error</p>
            }

            @if (_showSuccess)
            {
                <p class="success-message">Password updated successfully!</p>
            }

            <button class="btn-primary" @onclick="UpdatePasswordAsync" disabled="@_updating">
                @(_updating ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _error;
    private bool _updating;
    private bool _showSuccess;

    private async Task UpdatePasswordAsync()
    {
        _error = null;
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _error = "All fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _error = "New passwords do not match.";
            return;
        }

        _updating = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _showSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _updating = false;
        }
    }
}
"}

{"path": "/tmp/sv-bf366cbf07474dd7b8458053daff35c5/Components/Pages/Settings/ActiveSessionsTable.razor", "file_text": "@namespace sv_bf366cbf07474dd7b8458053daff35c5.Components.Pages.Settings
@using sv_bf366cbf07474dd7b8458053daff35c5.Services

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p>No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                @if (_confirmingSessionId == session.Id)
                                {
                                    <span class="confirm-revoke">
                                        <span>Revoke this session?</span>
                                        <button class="btn-danger btn-sm" @onclick="() => ConfirmRevokeAsync(session.Id)">Yes</button>
                                        <button class="btn-secondary btn-sm" @onclick="CancelRevoke">No</button>
                                    </span>
                                }
                                else
                                {
                                    <button class="btn-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">Revoke</button>
                                }
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }
</div>

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private string? _confirmingSessionId;

    private void RequestRevoke(string sessionId)
    {
        _confirmingSessionId = sessionId;
    }

    private void CancelRevoke()
    {
        _confirmingSessionId = null;
    }

    private async Task ConfirmRevokeAsync(string sessionId)
    {
        _confirmingSessionId = null;
        await OnRevoke.InvokeAsync(sessionId);
    }
}
"}

{"path": "/tmp/sv-bf366cbf07474dd7b8458053daff35c5/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_bf366cbf07474dd7b8458053daff35c5.Components.Pages.Settings
@using sv_bf366cbf07474dd7b8458053daff35c5.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security</h2>

    @if (_loading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <ChangePasswordPanel />

        <div class="two-factor-section">
            <h3>Two-Factor Authentication</h3>
            <div class="toggle-row">
                <span>
                    Two-Factor Authentication
                    <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </span>
                <input type="checkbox" @bind="_twoFactorEnabled" />
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @_lastPasswordChange.Value.ToString("f")</p>
            }
        </div>

        <ActiveSessionsTable Sessions="_sessions"
                             CurrentSessionId="@_currentSessionId"
                             OnRevoke="RevokeSessionAsync" />
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = [];
    private string _currentSessionId = "";

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        // Assume first session is current
        _currentSessionId = _sessions.FirstOrDefault()?.Id ?? "";
        _loading = false;
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions.RemoveAll(s => s.Id == sessionId);
    }
}
"}

