+        {
+            _error = "New passwords do not match.";
+            return;
+        }
+
+        _updating = true;
+        try
+        {
+            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
+            _showSuccess = true;
+            _currentPassword = "";
+            _newPassword = "";
+            _confirmPassword = "";
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _updating = false;
+        }
+    }
+}
