arguments.file_text:
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    display: flex;
    flex-direction: column;
    width: 220px;
    background: var(--bs-gray-100, #f8f9fa);
    border-right: 1px solid var(--bs-border-color, #dee2e6);
    padding: 1rem 0;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 0.95rem;
    color: var(--bs-body-color, #212529);
    text-align: left;
    transition: background-color 0.15s, border-left 0.15s;
    border-left: 3px solid transparent;
}

.sidebar-item:hover {
    background: var(--bs-gray-200, #e9ecef);
}

.sidebar-item.active {
    background: var(--bs-primary-bg-subtle, #cfe2ff);
    border-left-color: var(--bs-primary, #0d6efd);
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 0.375rem;
    font-size: 0.95rem;
}

.form-group textarea {
    resize: vertical;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Buttons */
.btn-primary {
    background: var(--bs-primary, #0d6efd);
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-weight: 500;
}

.btn-primary:hover {
    background: var(--bs-primary-hover, #0b5ed7);
}

.btn-secondary {
    background: var(--bs-gray-200, #e9ecef);
    color: var(--bs-body-color, #212529);
    border: 1px solid var(--bs-border-color, #dee2e6);
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    cursor: pointer;
}

.btn-danger {
    background: var(--bs-danger, #dc3545);
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    cursor: pointer;
}

.btn-sm {
    padding: 0.25rem 0.5rem;
    font-size: 0.8rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
}

.toast.success {
    background: var(--bs-success-bg-subtle, #d1e7dd);
    color: var(--bs-success-text-emphasis, #0a3622);
    border: 1px solid var(--bs-success-border-subtle, #a3cfbb);
}

/* Toggle rows */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.5rem 0;
}

/* Channels */
.channels-section {
    margin-bottom: 1.5rem;
}

.channels-section h3 {
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
}

.channel-row {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.375rem 0;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 0.5rem;
    margin-bottom: 1.5rem;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: var(--bs-gray-100, #f8f9fa);
    border: none;
    border-radius: 0.5rem;
    cursor: pointer;
    font-weight: 500;
}

.panel-body {
    padding: 1rem;
}

/* Status indicator */
.status-indicator {
    display: inline-block;
    padding: 0.2rem 0.5rem;
    border-radius: 0.25rem;
    font-size: 0.8rem;
    margin-left: 0.5rem;
}

.status-indicator.enabled {
    background: var(--bs-success-bg-subtle, #d1e7dd);
    color: var(--bs-success-text-emphasis, #0a3622);
}

.status-indicator.disabled {
    background: var(--bs-warning-bg-subtle, #fff3cd);
    color: var(--bs-warning-text-emphasis, #664d03);
}

.info-text {
    font-size: 0.85rem;
    color: var(--bs-secondary-color, #6c757d);
    margin-top: 0.5rem;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.625rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
}

.sessions-table th {
    font-weight: 600;
    font-size: 0.85rem;
    text-transform: uppercase;
    color: var(--bs-secondary-color, #6c757d);
}

.current-badge {
    font-size: 0.8rem;
    background: var(--bs-info-bg-subtle, #cff4fc);
    color: var(--bs-info-text-emphasis, #055160);
    padding: 0.2rem 0.5rem;
    border-radius: 0.25rem;
}

.confirm-revoke {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.85rem;
}

/* Avatar */
.avatar-preview {
    text-align: center;
    margin-bottom: 1.5rem;
}

.avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid var(--bs-border-color, #dee2e6);
}

.avatar-placeholder {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: var(--bs-gray-300, #dee2e6);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 0.8rem;
    color: var(--bs-secondary-color, #6c757d);
}

.avatar-url {
    font-size: 0.8rem;
    color: var(--bs-secondary-color, #6c757d);
    margin-top: 0.5rem;
    word-break: break-all;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-group label {
    display: flex;
    align-items: center;
    gap: 0.375rem;
    font-weight: normal;
}

/* Appearance preview */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 0.5rem;
    transition: all 0.2s;
}

.preview-area.dark-theme {
    background: #1a1a2e;
    color: #e0e0e0;
    border-color: #333;
}

.preview-area.light-theme {
    background: #ffffff;
    color: #212529;
}

.preview-area.system-theme {
    background: #f8f9fa;
    color: #212529;
}

.preview-area.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-area h4 {
    margin-bottom: 0.5rem;
}

/* Two-factor section */
.two-factor-section {
    margin-bottom: 1.5rem;
}

.two-factor-section h3 {
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
}

/* Messages */
.error-message {
    color: var(--bs-danger, #dc3545);
    font-size: 0.9rem;
    margin-bottom: 0.75rem;
}

.success-message {
    color: var(--bs-success, #198754);
    font-size: 0.9rem;
    margin-bottom: 0.75rem;
}

.loading {
    color: var(--bs-secondary-color, #6c757d);
    font-style: italic;
}

using sv_bf366cbf07474dd7b8458053daff35c5.Services;

namespace sv_bf366cbf07474dd7b8458053daff35c5.Services;

/// <summary>
/// In-memory stub implementation for demonstration purposes.
/// Replace with a real implementation backed by a database or API.
/// </summary>
public class InMemorySettingsService : ISettingsService
{
    private UserProfile _profile = new("Jane Doe", "jane@example.com", "https://i.pravatar.cc/150?u=jane", "Software developer and coffee enthusiast.");
    private NotificationPrefs _notificationPrefs = new(true, true, false, ["Random"]);
    private SecuritySettings _security = new(
        true,
        DateTime.UtcNow.AddDays(-30),
        [
            new("sess-1", "Chrome on Windows", "New York, US", DateTime.UtcNow.AddMinutes(-5)),
            new("sess-2", "Safari on iPhone", "New York, US", DateTime.UtcNow.AddHours(-2)),
            new("sess-3", "Firefox on Linux", "London, UK", DateTime.UtcNow.AddDays(-1))
        ]);
    private AppearanceSettings _appearance = new("System", "Medium", "en", false);

    public Task<UserProfile> GetProfileAsync() => Task.FromResult(_profile);

    public Task SaveProfileAsync(UserProfile profile)
    {
        _profile = profile;
        return Task.CompletedTask;
    }

    public Task<NotificationPrefs> GetNotificationPrefsAsync() => Task.FromResult(_notificationPrefs);

    public Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        _notificationPrefs = prefs;
        return Task.CompletedTask;
    }

    public Task<SecuritySettings> GetSecuritySettingsAsync() => Task.FromResult(_security);

    public Task ChangePasswordAsync(string currentPassword, string newPassword)
    {
        if (string.IsNullOrWhiteSpace(currentPassword))
            throw new InvalidOperationException("Current password is required.");

        _security = _security with { LastPasswordChange = DateTime.UtcNow };
        return Task.CompletedTask;
    }

    public Task RevokeSessionAsync(string sessionId)
    {
        var updated = _security.Sessions.Where(s => s.Id != sessionId).ToList();
        _security = _security with { Sessions = updated };
        return Task.CompletedTask;
    }

    public Task<AppearanceSettings> GetAppearanceAsync() => Task.FromResult(_appearance);

    public Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        _appearance = settings;
        return Task.CompletedTask;
    }
}

