+    padding: 0.2rem 0.5rem;
+    border-radius: 0.25rem;
+}
+
+.confirm-revoke {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    font-size: 0.85rem;
+}
+
+/* Avatar */
+.avatar-preview {
+    text-align: center;
+    margin-bottom: 1.5rem;
+}
+
+.avatar-image {
+    width: 80px;
+    height: 80px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 2px solid var(--bs-border-color, #dee2e6);
+}
+
+.avatar-placeholder {
+    width: 80px;
+    height: 80px;
+    border-radius: 50%;
+    background: var(--bs-gray-300, #dee2e6);
+    display: inline-flex;
+    align-items: center;
+    justify-content: center;
+    font-size: 0.8rem;
+    color: var(--bs-secondary-color, #6c757d);
+}
+
+.avatar-url {
+    font-size: 0.8rem;
+    color: var(--bs-secondary-color, #6c757d);
+    margin-top: 0.5rem;
+    word-break: break-all;
+}
+
+/* Radio group */
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
+}
+
+.radio-group label {
+    display: flex;
+    align-items: center;
+    gap: 0.375rem;
+    font-weight: normal;
+}
+
+/* Appearance preview */
+.preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 1px solid var(--bs-border-color, #dee2e6);
+    border-radius: 0.5rem;
+    transition: all 0.2s;
+}
+
+.preview-area.dark-theme {
+    background: #1a1a2e;
+    color: #e0e0e0;
+    border-color: #333;
+}
+
+.preview-area.light-theme {
+    background: #ffffff;
+    color: #212529;
+}
+
+.preview-area.system-theme {
+    background: #f8f9fa;
+    color: #212529;
+}
+
+.preview-area.compact {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+
+.preview-area h4 {
+    margin-bottom: 0.5rem;
+}
+
+/* Two-factor section */
+.two-factor-section {
+    margin-bottom: 1.5rem;
+}
+
+.two-factor-section h3 {
+    font-size: 1.1rem;
+    margin-bottom: 0.75rem;
+}
+
+/* Messages */
+.error-message {
+    color: var(--bs-danger, #dc3545);
+    font-size: 0.9rem;
+    margin-bottom: 0.75rem;
+}
+
+.success-message {
+    color: var(--bs-success, #198754);
+    font-size: 0.9rem;
+    margin-bottom: 0.75rem;
+}
+
+.loading {
+    color: var(--bs-secondary-color, #6c757d);
+    font-style: italic;
+}
